namespace QuickCode.QuickCode.Infrastructure.Web.Filters;

/// <summary>
/// NSwag/HTTP clients encode <c>/</c> as <c>%2F</c>. ASP.NET does not decode that in a route segment,
/// so queries like GetApiMethodDefinitionsByUrl("/") ran as LIKE '%2F%' and returned almost nothing.
/// </summary>
public sealed class UnescapeRouteStringParametersAttribute : ActionFilterAttribute
{
    public override void OnActionExecuting(ActionExecutingContext context)
    {
        foreach (var key in context.ActionArguments.Keys.ToList())
        {
            if (!context.RouteData.Values.ContainsKey(key))
                continue;

            if (context.ActionArguments[key] is string value)
                context.ActionArguments[key] = Decode(value);
        }
    }

    internal static string Decode(string value)
    {
        if (string.IsNullOrEmpty(value) || value.IndexOf('%') < 0)
            return value;

        try
        {
            return Uri.UnescapeDataString(value);
        }
        catch (UriFormatException)
        {
            return value;
        }
    }
}
